shortcuts.codeOnPrepare:
var raw = getVariable('shared_input').trim();
var fromShare = /https?:\/\//.test(raw);
var lines = raw.split('\n').map(function(s){return s.trim();}).filter(function(s){return s && s.indexOf('http') !== 0;});
var name = (lines.length > 0 ? lines[0] : raw);
function clean(s) {
  s = s.replace(/https?:\/\/\S+/g, '');
  s = s.replace(/\s*[-–—·|:,]?\s*Google Maps\s*$/i, '');
  s = s.replace(/[\s\-–—·|:,]+$/, '');
  s = s.replace(/^[\s\-–—·|:,]+/, '');
  return s.trim();
}
name = clean(name);
while (!name) {
  var redo = prompt('内容不能为空,重新输入:');
  if (redo === null) { showToast('已取消,未写入'); abort(); }
  name = redo.trim();
}
var tag;
if (fromShare) {
  tag = 'Restaurant';
} else {
  tag = showSelection(['Restaurant','Outdoors','Travel','Home','Exhibition','Show','Shops','Social','Concert','Study','Cafe'], 'Tag');
  if (tag === null) { showToast('已取消,未写入'); abort(); }
}
while (true) {
  if (confirm('记入 Notion:\n' + name + ' · ' + tag + ' · 今天')) { break; }
  var edited = prompt('修改内容(按取消 = 放弃):', name);
  if (edited === null) { showToast('已取消,未写入'); abort(); }
  edited = edited.trim();
  if (edited) { name = edited; }
}
setVariable('clean_name', name);
setVariable('clean_tag', tag);

shortcuts.codeOnSuccess:
var page = JSON.parse(response.body);
if (page && page.url) {
  if (confirm('已记入 ✓  打开 Notion 查看?')) {
    try { openUrl(page.url, 'notion.id'); }
    catch (e) { openUrl(page.url); }
  } else { showToast('已记入 ✓'); }
} else { showToast('已记入 ✓'); }

